#!/bin/sh
# Offline stand-in for `aeneas -backend lean -namespace NS -dest DIR FILE.llbc`:
# writes DIR/NS.lean from the LLBC file.
ns=""; dest=""; file=""
while [ $# -gt 0 ]; do
  case "$1" in
    -namespace) ns="$2"; shift ;;
    -dest) dest="$2"; shift ;;
    -backend) shift ;;
    *) file="$1" ;;
  esac
  shift
done
{ echo "-- THIS FILE WAS AUTOMATICALLY GENERATED BY AENEAS"; echo "namespace $ns"; sed 's/^/-- /' "$file"; echo "end $ns"; } > "$dest/$ns.lean"
echo "[Info ] Generated: $dest/$ns.lean"
